\begin{tikzpicture}[
  >=Stealth,
  every node/.style={font=\footnotesize},
  box/.style={draw, rounded corners, inner sep=3pt, minimum height=6mm, align=center},
  fact/.style={box, dashed,
    label={[font=\scriptsize, gray, label distance=-1pt]below:restated}},
  edge/.style={->, gray!70},
  iface/.style={->, dotted, gray!60},
]


\node[fact] (kmv)   at (0,0)        {\cref{fact:kmv}};
\node[box]  (taste) at (6.8,0)      {\cref{thm:taste}};
\node[box]  (abel)  at (10.2,0)     {\cref{thm:abelian}};

\node[box] (sand)  at (3.4,-1.0)    {\cref{lem:sandwich}};
\node[box] (fresh) at (3.4,-2.0)    {\cref{lem:fresh}};
\node[box] (flood) at (6.8,-1.5)    {\cref{thm:flood}};

\node[box] (comp)  at (3.4,-3.0)    {\cref{lem:composition}};
\node[box] (race)  at (3.4,-4.1)    {\cref{lem:race}};
\node[box] (caps)  at (6.8,-3.5)    {\cref{thm:caps}};

\node[fact] (kw)   at (0,-5.5)      {\cref{fact:kw16,fact:kw25}};
\node[box]  (ptr)  at (3.4,-6.5)    {\cref{lem:pointer}};
\node[box]  (harvest) at (6.8,-5.5) {\cref{thm:harvest}};

\node[box] (iface) at (10.2,-1.9)   {\cref{rmk:interface}};
\node[box] (dich)  at (10.2,-3.7)   {\cref{cor:dichotomy}};
\node[box] (free)  at (10.2,-5.5)   {\cref{prop:free}};
\node[box] (prec)  at (10.2,-6.7)   {\cref{prop:precision}};

\draw[edge] (kmv)   -- (taste);
\draw[edge] (taste) -- (abel);
\draw[edge] (sand)  -- (flood);
\draw[edge] (fresh) -- (flood);
\draw[edge] (comp)  -- (caps);
\draw[edge] (race)  -- (caps);
\draw[edge] (race)  -- (harvest);
\draw[edge] (ptr)   -- (harvest);
\draw[edge] (kw)    -- (harvest);
\draw[edge] (caps)    -- (dich);
\draw[edge] (harvest) -- (dich);
\draw[iface] (caps) -- (iface) node[midway, above, sloped] {\scriptsize interface};
\draw[edge] (iface) to[bend left=52, looseness=1.15] (free);
\draw[edge] (ptr)   to[bend right=10] (free);
\draw[edge] (free)  -- (prec);
\end{tikzpicture}
\caption{Dependency map. Dashed boxes are restated prior facts; solid boxes are
results of this paper. The impossibility theorem (\cref{thm:caps}) and the
achievability theorem (\cref{thm:harvest}) meet at the dichotomy
(\cref{cor:dichotomy}); the case study (\cref{thm:abelian}, \cref{prop:free},
\cref{prop:precision}) reads the dichotomy off the interface of
\cref{rmk:interface}.}
\label{fig:map}
\end{figure}

